//! Independent numerical parity for the complete PyIN + Viterbi pipeline.
//!
//! Fixtures come from `librosa.pyin` 0.11.0 at revision
//! `af8c839fb15317fa2712ea66e7a22da6a9267b32`, generated by
//! `tools/parity/pyin_dump_reference.py`. The clip covers silence boundaries,
//! steady 220/330 Hz tones, and a deliberately short 440 Hz octave excursion.

use vokra_ops::pyin_detailed;

const PCM_BYTES: &[u8] = include_bytes!("fixtures/pyin/pcm.f32.bin");
const F0_BYTES: &[u8] = include_bytes!("fixtures/pyin/f0.f32.bin");
const VOICED_BYTES: &[u8] = include_bytes!("fixtures/pyin/voiced.u8.bin");
const CONFIDENCE_BYTES: &[u8] = include_bytes!("fixtures/pyin/confidence.f32.bin");

fn f32_le(bytes: &[u8]) -> Vec<f32> {
    assert_eq!(bytes.len() % 4, 0);
    bytes
        .chunks_exact(4)
        .map(|chunk| f32::from_le_bytes(chunk.try_into().expect("four bytes")))
        .collect()
}

#[test]
fn complete_pyin_matches_librosa_reference() {
    let pcm = f32_le(PCM_BYTES);
    let reference_f0 = f32_le(F0_BYTES);
    let reference_confidence = f32_le(CONFIDENCE_BYTES);
    let actual = pyin_detailed(&pcm, 16_000, 65.0, 800.0).expect("PyIN forward");

    assert_eq!(actual.len(), 121);
    assert_eq!(reference_f0.len(), actual.len());
    assert_eq!(VOICED_BYTES.len(), actual.len());
    assert_eq!(reference_confidence.len(), actual.len());

    let mut max_f0_abs = 0.0f32;
    let mut max_confidence_abs = 0.0f32;
    let mut voiced_mismatches = Vec::new();
    for (index, frame) in actual.iter().enumerate() {
        max_f0_abs = max_f0_abs.max((frame.hz - reference_f0[index]).abs());
        max_confidence_abs =
            max_confidence_abs.max((frame.confidence - reference_confidence[index]).abs());
        if frame.voiced != (VOICED_BYTES[index] != 0) {
            voiced_mismatches.push(index);
        }
    }

    // F0 is decoded onto the same 0.1-semitone grid, so matching state paths
    // differ only by the final f64->f32 frequency calculation.
    assert!(
        max_f0_abs <= 1e-3,
        "max |F0_vokra-F0_librosa| = {max_f0_abs} Hz"
    );
    assert!(
        voiced_mismatches.is_empty(),
        "voiced-state mismatches at frames {voiced_mismatches:?}"
    );
    // The direct O(N*tau) Rust autocorrelation accumulates in f64 while
    // librosa's oracle uses its FFT/autocorrelation numerical path. A fixed
    // 2e-4 bound covers the resulting probability rounding without hiding a
    // threshold-bin or observation-model error.
    assert!(
        max_confidence_abs <= 2e-4,
        "max |confidence_vokra-confidence_librosa| = {max_confidence_abs}"
    );
}
